Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='warningsaretodos', at=datetime(2026, 11, 4, 0, 0, 0), actor='owner', title='A warning about something coming is a dated todo, never a card or a new notice kind', body="To remind before an event (a token's expiry, a renewal, a deadline), write one todo with the event as its deadline, once per event, completed by the act that settles it. The chain's priority brings it forward as the day nears. A card is only for an answer the owner must give now.", rationale='The owner, 2026-11-04: such warnings are just todos.', supersedes=()))